func TestU7SerializeGivesTheKindOfPhpValueInValue(t *testing.T) {
	_, err := Serialize(func() {})
	if failure, ok := err.(*liberrors.FormatError); !ok || failure.Kind() != "unsupported_value" {
		t.Fatalf("U-7: %#v", err)
	}
}

func TestB4SerializePropertyNul(t *testing.T) {
	object0 := must(binding.NewStdClass(nil))
	object0.Properties.Set(binding.BytesKey([]byte("\x00a")), int64(1))
	_, err := Serialize(object0)
	failure, ok := err.(*liberrors.FormatError)
	if !ok || failure.Kind() != "property_name" {
		t.Fatalf("B-4: %#v", err)
	}
	var category *liberrors.PHPSerializationValueError
	if !errors.As(err, &category) {
		t.Fatalf("E-2: %#v is no error of its category", err)
	}
	if _, ok := failure.Status(); ok {
		t.Fatalf("B-4: the status of %#v", err)
	}
	if _, ok := failure.Errno(); ok {
		t.Fatalf("B-4: the errno of %#v", err)
	}
}

