func TestGN13eSerializeASharedReferenceIsOneReference(t *testing.T) {
	reference0 := must(binding.NewReference(nil))
	reference0.Value = int64(1)
	entries1 := &binding.KeyedMap[any]{}
	entries1.Set(binding.IntKey(0), reference0)
	entries1.Set(binding.IntKey(1), reference0)
	value0, err := Serialize(entries1)
	if err != nil {
		t.Fatalf("GN-13e: %v", err)
	}
	if want := ([]byte)([]byte("a:2:{i:0;i:1;i:1;R:2;}")); !reflect.DeepEqual(value0, want) {
		t.Fatalf("GN-13e: %#v is not %#v", value0, want)
	}
}

func TestB4StdClassNewAPropertyNameWithNulIsRefused(t *testing.T) {
	entries0 := &binding.KeyedMap[any]{}
	entries0.Set(binding.BytesKey([]byte("\x00a")), int64(1))
	_, err := NewStdClass(entries0)
	failure, ok := err.(*liberrors.FormatError)
	if !ok || failure.Kind() != "property_name" {
		t.Fatalf("B-4: %#v", err)
	}
	var category *liberrors.PHPSerializationValueError
	if !errors.As(err, &category) {
		t.Fatalf("E-2: %#v is no error of its category", err)
	}
	if _, ok := failure.Status(); ok {
		t.Fatalf("B-4: the status of %#v", err)
	}
	if _, ok := failure.Errno(); ok {
		t.Fatalf("B-4: the errno of %#v", err)
	}
}

